@dp.error()
async def maker_error_handler(event: ErrorEvent):
    """Keep the Maker process alive on handler errors.

    Telegram can reject duplicate message edits with `message is not modified`.
    Treat that as a harmless stale/duplicate callback. Other update-handler
    exceptions are logged and consumed so one bad update cannot terminate the
    Railway worker.
    """
    exc = event.exception
    if isinstance(exc, TelegramBadRequest) and "message is not modified" in str(exc).lower():
        print("[MAKER] Ignored harmless TelegramBadRequest: message is not modified", flush=True)
        return True
    print(f"[MAKER] Ignored update exception: {type(exc).__name__}: {exc}", flush=True)
    return True

