# Per-instance process supervision. Each generated Shop Bot has its own
# subprocess, database and event loop, so one child crashing does not stop
# the others. Restarts use bounded backoff to avoid a tight crash loop.
SUPERVISOR_INTERVAL = float(os.getenv("BOT_SUPERVISOR_INTERVAL", "5"))
RESTART_BASE_DELAY = float(os.getenv("BOT_RESTART_BASE_DELAY", "3"))
RESTART_MAX_DELAY = float(os.getenv("BOT_RESTART_MAX_DELAY", "60"))

def _instance_lock(instance_id):
    lock = process_locks.get(instance_id)
    if lock is None:
        lock = asyncio.Lock()
        process_locks[instance_id] = lock
    return lock


def db():
    conn = sqlite3.connect(DB_PATH)
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("CREATE TABLE IF NOT EXISTS instances (id TEXT PRIMARY KEY, name TEXT NOT NULL, token TEXT NOT NULL, admin_id INTEGER NOT NULL, username TEXT DEFAULT '', created_at TEXT NOT NULL, active INTEGER DEFAULT 1, creator_id INTEGER DEFAULT 0)")
    try: conn.execute("ALTER TABLE instances ADD COLUMN banned INTEGER DEFAULT 0")
    except sqlite3.OperationalError: pass
    try: conn.execute("ALTER TABLE instances ADD COLUMN creator_id INTEGER DEFAULT 0")
    except sqlite3.OperationalError: pass
    conn.execute("CREATE TABLE IF NOT EXISTS license_payments (order_id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, amount_inr REAL NOT NULL, gateway_amount REAL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending', created_at REAL NOT NULL, utr TEXT DEFAULT '')")
    for col, typ in (("instance_id", "TEXT DEFAULT ''"), ("admin_id", "INTEGER DEFAULT 0"), ("bot_token", "TEXT DEFAULT ''"), ("duration_days", "INTEGER DEFAULT 30")):
        try: conn.execute(f"ALTER TABLE license_payments ADD COLUMN {col} {typ}")
        except sqlite3.OperationalError: pass
    conn.execute("CREATE TABLE IF NOT EXISTS payment_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL DEFAULT '')")
    conn.execute("CREATE TABLE IF NOT EXISTS issued_keys (id INTEGER PRIMARY KEY AUTOINCREMENT, key_hash TEXT UNIQUE NOT NULL, key_plain TEXT NOT NULL, instance_id TEXT DEFAULT '', user_id INTEGER DEFAULT 0, issued_at TEXT NOT NULL, expires_at TEXT NOT NULL, revoked INTEGER DEFAULT 0, activated_at TEXT DEFAULT '')")
    conn.execute("CREATE TABLE IF NOT EXISTS maker_users (user_id INTEGER PRIMARY KEY, first_name TEXT DEFAULT '', username TEXT DEFAULT '', phone TEXT DEFAULT '', joined_at TEXT NOT NULL, is_banned INTEGER DEFAULT 0)")
    conn.commit()
    return conn


def setting(key, default=""):
    conn = db(); row = conn.execute("SELECT value FROM payment_settings WHERE key=?", (key,)).fetchone(); conn.close()
    return row[0] if row else default


def set_setting(key, value):
    conn = db(); conn.execute("INSERT INTO payment_settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (key, str(value))); conn.commit(); conn.close()


