@dp.message(PaymentSettings.field)
async def save_payment_field(message: Message, state: FSMContext):
    if not owner_only(message): return
    value=(message.text or "").strip()
    if value.lower() == "/cancel":
        await state.clear(); return await message.answer("Cancelled.", reply_markup=payment_kb())
    data=await state.get_data(); field=data.get("payment_field")
    if field == "gateway_url":
        candidate=value.rstrip("/"); parsed=urlparse(candidate)
        if parsed.scheme not in ("http", "https") or not parsed.netloc:
            return await message.answer("❌ Invalid URL. Example: <code>https://famgateway.in</code>", parse_mode="HTML")
        set_setting(field, candidate)
    elif field == "gateway_api_key":
        if len(value) < 6: return await message.answer("❌ API key looks too short.")
        set_setting(field, value)
    elif field == "upi_id":
        if "@" not in value or len(value) < 5: return await message.answer("❌ Invalid UPI ID.")
        set_setting(field, value)
    elif field == "support_url":
        candidate=value.rstrip("/")
        parsed=urlparse(candidate)
        if parsed.scheme not in ("http","https") or not parsed.netloc:
            return await message.answer("❌ Invalid support URL.", parse_mode="HTML")
        set_setting(field, candidate)
    elif field == "bot_price":
        try: price=float(value)
        except: return await message.answer("❌ Price must be a number, e.g. 100")
        if price < 1: return await message.answer("❌ Price must be at least ₹1.")
        set_setting(field, f"{price:.2f}")
    elif field in {"plan_1_price", "plan_7_price", "plan_15_price", "plan_30_price", "plan_2m_price", "plan_6m_price", "plan_1y_price"}:
        try: price=float(value)
        except: return await message.answer("❌ Price must be a number, e.g. 100")
        if price < 1: return await message.answer("❌ Price must be at least ₹1.")
        set_setting(field, f"{price:.2f}")
    else:
        return await message.answer("❌ Unknown setting.")
    await state.clear(); await message.answer("✅ Setting saved.", reply_markup=payment_kb())


@dp.callback_query(F.data == "pay_test")
async def pay_test(call: CallbackQuery):
    if call.from_user.id != OWNER_ID: return await call.answer("Owner only", show_alert=True)
    base=setting("gateway_url", "https://famgateway.in").rstrip("/"); key=setting("gateway_api_key")
    if not key: return await call.answer("Set the Gateway API Key first.", show_alert=True)
    await call.answer("Testing gateway...", show_alert=False)
    try:
        async with aiohttp.ClientSession() as session:
            async with session.get(f"{base}/api/verify-order.php", params={"api_key":key,"order_id":"TEST-INVALID-ORDER"}, timeout=aiohttp.ClientTimeout(total=15)) as resp:
                if resp.status in (200,400,404,408): msg=f"✅ Gateway reachable. HTTP {resp.status}."
                elif resp.status == 401: msg="❌ API key rejected (401)."
                else: msg=f"⚠️ Gateway returned HTTP {resp.status}."
    except Exception as e: msg=f"❌ Connection failed: {type(e).__name__}: {e}"
    await call.message.edit_text(f"🧪 <b>Gateway Test</b>\n\n🌐 <code>{base}</code>\n{msg}", reply_markup=payment_kb(), parse_mode="HTML")


# ---------------------- Paid bot creation ----------------------
def _new_order_id():
    return f"BOT{int(time.time())}{secrets.randbelow(900000)+100000}"


def _new_license_key():
    return "OBITO_ADMIN_1-" + secrets.token_urlsafe(18).replace("-", "X").replace("_", "Y")


def _hash_key(value):
    return hashlib.sha256(value.strip().encode()).hexdigest()


def ensure_admin_license(instance_id, admin_id, days=30):
    """Issue an admin key whose validity starts when the Shop Bot activates it."""
    license_db=DATA_DIR / "licenses.db"
    conn=sqlite3.connect(license_db, timeout=10, check_same_thread=False)
    conn.execute("CREATE TABLE IF NOT EXISTS issued_keys (id INTEGER PRIMARY KEY AUTOINCREMENT, key_hash TEXT UNIQUE NOT NULL, key_plain TEXT DEFAULT '', instance_id TEXT DEFAULT '', user_id INTEGER DEFAULT 0, issued_at TEXT NOT NULL, expires_at TEXT NOT NULL, revoked INTEGER DEFAULT 0, activated_at TEXT DEFAULT '', duration_days INTEGER DEFAULT 30)")
    try: conn.execute("ALTER TABLE issued_keys ADD COLUMN duration_days INTEGER DEFAULT 30")
    except sqlite3.OperationalError: pass
    conn.execute("CREATE TABLE IF NOT EXISTS activations (id INTEGER PRIMARY KEY AUTOINCREMENT, instance_id TEXT NOT NULL, user_id INTEGER NOT NULL, key_hash TEXT NOT NULL, activated_at TEXT NOT NULL, expires_at TEXT NOT NULL, revoked INTEGER DEFAULT 0, UNIQUE(instance_id,user_id), UNIQUE(key_hash))")
    duration_days=max(1, int(days))
    now=datetime.now(timezone.utc).replace(tzinfo=None)
    key=_new_license_key(); h=_hash_key(key)
    # IMPORTANT: expires_at stays blank until /activate in the Shop Bot.
    conn.execute("INSERT INTO issued_keys(key_hash,key_plain,instance_id,user_id,issued_at,expires_at,revoked,activated_at,duration_days) VALUES(?,?,?,?,?,?,0,'',?)",(h,key,instance_id,admin_id,now.isoformat(),'',duration_days))
    conn.commit(); conn.close(); return key, f"Starts on activation • {duration_days} day(s)"


