        conn=db(); conn.execute("UPDATE license_payments SET status='expired' WHERE order_id=?",(order_id,)); conn.commit(); conn.close(); return await call.message.edit_text("⏳ Payment expired. Please start Buy Key again.",reply_markup=kb_home(call.from_user.id))
