async def create_instance_from_setup(message: Message, state: FSMContext):
    """Create and immediately launch a Shop Bot from token + Chat/Admin ID."""
    if user_is_banned(message.from_user.id):
        await state.clear()
        return

    data=await state.get_data()
    admin_id=int(data.get("admin_id", 0) or 0)
    token=(data.get("token") or "").strip()
    username=data.get("username") or ""
    if not admin_id or not token:
        await state.clear()
        return await message.answer("❌ Setup data is incomplete. Please press Create Bot again.")

    instance_id=secrets.token_hex(5)
    inst_dir=INST_DIR/instance_id
    inst_dir.mkdir(parents=True,exist_ok=True)
    creator_id=message.from_user.id

    conn=db()
    conn.execute(
        "INSERT INTO instances(id,name,token,admin_id,username,created_at,active,creator_id) "
        "VALUES(?,?,?,?,?,?,1,?)",
        (instance_id, data.get("name") or ("@"+username if username else "Shop Bot"),
         token, admin_id, username, datetime.now(timezone.utc).replace(tzinfo=None).isoformat(), creator_id)
    )
    conn.commit()
    conn.close()

    # Owner's explicit free-create override may issue a license immediately.
    free_key=None
    free_key_exp=None
    if creator_id == OWNER_ID and bool(data.get("free_override")):
        try:
            free_key, free_key_exp = ensure_admin_license(instance_id, admin_id)
        except Exception:
            free_key, free_key_exp = None, None

    try:
        started=await launch_instance(instance_id)
    except Exception as exc:
        started=False
        conn=db()
        conn.execute("UPDATE instances SET active=0 WHERE id=?", (instance_id,))
        conn.commit()
        conn.close()
        logger.exception("Failed to launch Shop Bot %s", instance_id)

    await state.clear()

    if not started:
        result_text=(
            "⚠️ <b>Bot saved, but it could not be started right now.</b>\n\n"
            f"🤖 @{username or 'unknown'}\n"
            f"🆔 Instance: <code>{instance_id}</code>\n"
            f"👤 Chat/Admin ID: <code>{admin_id}</code>\n\n"
            "Use <code>/restart INSTANCE_ID</code> after fixing the token/hosting issue."
        )
    else:
        result_text=(
            "🎉 <b>Bot Created & Started</b>\n\n"
            f"🤖 @{username or 'unknown'}\n"
            f"🆔 Instance: <code>{instance_id}</code>\n"
            f"👤 Chat/Admin ID: <code>{admin_id}</code>\n\n"
            "🟢 Shop Bot is now running from <code>shop_bot_multi_api_fixed.py</code>.\n"
            "It will be supervised and restarted if the process stops.\n\n"
            "🔒 Admin Panel needs a valid license key; normal Shop/customer use is separate."
        )
    if free_key:
        result_text += (
            f"\n\n🎁 <b>OWNER FREE BOT LICENSE KEY</b>\n<code>{free_key}</code>"
            f"\n\nActivate from the configured Admin ID with <code>/activate {free_key}</code>."
        )
    await message.answer(result_text, reply_markup=kb_home(message.from_user.id), parse_mode="HTML")

    if admin_id != message.from_user.id:
        try:
            await bot.send_message(
                admin_id,
                f"🤖 <b>Shop Bot Started</b>\n\n"
                f"Bot: @{username or 'unknown'}\n"
                f"Instance: <code>{instance_id}</code>\n"
                f"Chat/Admin ID: <code>{admin_id}</code>\n\n"
                "Your Shop Bot is running. Admin Panel requires a valid license key.",
                parse_mode="HTML"
            )
        except Exception:
            pass


async def launch_instance(instance_id):
    async with _instance_lock(instance_id):
        current = processes.get(instance_id)
        if current and current.poll() is None:
            return True
        conn=db(); row=conn.execute("SELECT name,token,admin_id,username,active,COALESCE(banned,0) FROM instances WHERE id=?",(instance_id,)).fetchone(); conn.close()
        if not row or not row[4] or row[5]:
            processes.pop(instance_id, None)
            return False
        name,token,admin_id,username,_,_=row
        inst_dir=INST_DIR/instance_id
        inst_dir.mkdir(parents=True,exist_ok=True)

        import json
        child_env=os.environ.copy(); child_env.update({
            "BOT_TOKEN":token,
            "BOT_USERNAME":"@"+username if username else "@shop_bot",
            "ADMIN_ID":str(admin_id),
            "SECOND_ADMIN_ID":"0",
            "ADMIN_CONTACT":"",
            "SHOP_DB_PATH":str(inst_dir/"shop.db"),
            "LICENSE_DB":str(DATA_DIR/"licenses.db"),
            "LICENSE_ENFORCED":"1",
            "INSTANCE_ID":instance_id,
            "LICENSE_PAYMENT_BASE_URL":setting("gateway_url","https://famgateway.in"),
            "LICENSE_PAYMENT_API_KEY":setting("gateway_api_key",""),
            "LICENSE_PRICE_INR":setting("bot_price","100"),
            "LICENSE_PLANS_JSON":json.dumps({"1":{"days":1,"price":float(setting("plan_1_price","20"))},"7":{"days":7,"price":float(setting("plan_7_price","35"))},"15":{"days":15,"price":float(setting("plan_15_price","50"))},"30":{"days":30,"price":float(setting("plan_30_price","90"))},"2m":{"days":60,"price":float(setting("plan_2m_price","150"))},"6m":{"days":180,"price":float(setting("plan_6m_price","350"))},"1y":{"days":365,"price":float(setting("plan_1y_price","600"))}}),
            "PYTHONUNBUFFERED":"1",
        })
        # Separate log handle per child; keep the handle alive for the whole
        # child lifetime so output is never accidentally closed by GC.
        log_path=inst_dir/"bot.log"
        log=process_logs.get(instance_id)
        if log is None or log.closed:
            log=open(log_path,"a",encoding="utf-8",buffering=1)
            process_logs[instance_id]=log
        try:
            p=subprocess.Popen(
                [sys.executable,"-u",str(TEMPLATE),"--child"],
                cwd=str(inst_dir),
                env=child_env,
                stdout=log,
                stderr=log,
                stdin=subprocess.DEVNULL,
                close_fds=True,
            )
        except Exception:
            try: log.flush()
            except Exception: pass
            raise
        processes[instance_id]=p
        restart_state[instance_id]={"failures":0,"next_at":0.0,"pid":p.pid}
        return True

async def _stop_instance_process(instance_id):
    async with _instance_lock(instance_id):
        p=processes.get(instance_id)
        if not p:
            return
        try:
            if p.poll() is None:
                p.terminate()
                try:
                    await asyncio.wait_for(asyncio.to_thread(p.wait), timeout=5)
                except asyncio.TimeoutError:
                    if p.poll() is None:
                        p.kill()
                        await asyncio.to_thread(p.wait)
        except Exception:
            pass
        processes.pop(instance_id,None)
        restart_state.pop(instance_id,None)

async def supervise_instances():
    """Keep all active generated Shop Bots alive independently."""
    while True:
        try:
            conn=db(); rows=conn.execute("SELECT id FROM instances WHERE active=1 AND COALESCE(banned,0)=0").fetchall(); conn.close()
            active_ids={r[0] for r in rows}
            # Stop stale in-memory processes that were disabled/banned.
            for iid in list(processes):
                if iid not in active_ids:
                    await _stop_instance_process(iid)

            now=time.monotonic()
            for iid in active_ids:
                p=processes.get(iid)
                if p and p.poll() is None:
                    continue
                state=restart_state.setdefault(iid,{"failures":0,"next_at":0.0,"pid":None})
                if now < float(state.get("next_at",0)):
                    continue
                try:
                    ok=await launch_instance(iid)
                    if ok:
                        state["failures"]=0
                        state["next_at"]=0.0
                except Exception as exc:
                    failures=int(state.get("failures",0))+1
                    state["failures"]=failures
                    delay=min(RESTART_MAX_DELAY, RESTART_BASE_DELAY*(2**min(failures-1,5)))
                    state["next_at"]=now+delay
                    print(f"[SUPERVISOR] failed to start {iid}: {type(exc).__name__}; retry in {delay:.1f}s", flush=True)
                await asyncio.sleep(0)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            print(f"[SUPERVISOR] loop error: {type(exc).__name__}: {exc}", flush=True)
        await asyncio.sleep(SUPERVISOR_INTERVAL)

