def child_bot_stats(instance_id):
    """Read non-sensitive user statistics from a generated bot's local shop DB."""
    path=INST_DIR/instance_id/"shop.db"
    if not path.exists(): return 0, []
    try:
        conn=sqlite3.connect(path)
        count=conn.execute("SELECT COUNT(*) FROM users").fetchone()[0]
        rows=conn.execute("SELECT user_id,first_name,username,phone FROM users ORDER BY rowid DESC LIMIT 20").fetchall()
        conn.close()
        return int(count), rows
    except Exception:
        return 0, []

@dp.callback_query(F.data == "bot_history")
async def bot_history(call: CallbackQuery):
    if call.from_user.id != OWNER_ID: return await call.answer("Owner only",show_alert=True)
    conn=db()
    rows=conn.execute("""SELECT i.id,i.name,i.username,i.admin_id,i.creator_id,i.created_at,i.active,COALESCE(i.banned,0),
                              COALESCE(mu.first_name,''),COALESCE(mu.username,''),COALESCE(mu.phone,'')
                       FROM instances i LEFT JOIN maker_users mu ON mu.user_id=i.creator_id
                       ORDER BY i.created_at DESC""").fetchall()
    conn.close()
    if not rows:
        return await call.message.edit_text("🧾 <b>BOT HISTORY</b>\n\nNo Shop Bots created yet.",reply_markup=kb_home(OWNER_ID),parse_mode="HTML")
    # Show only metadata, never bot tokens. Include the creator's saved phone number when available.
    license_db=DATA_DIR / "licenses.db"
    lines=[]
    for iid,name,user,admin,creator,created,active,banned,first,uname,phone in rows:
        status="🚫 BANNED" if banned else ("🟢 ACTIVE" if active else "🔴 STOPPED")
        lconn=sqlite3.connect(license_db)
        keyrow=lconn.execute("SELECT key_plain,expires_at,revoked FROM issued_keys WHERE instance_id=? AND user_id=? ORDER BY id DESC LIMIT 1",(iid,admin)).fetchone()
        lconn.close()
        key_line="🔑 Key: <code>not issued</code>"
        if keyrow and not keyrow[2]:
            key_line=f"🔑 Key: <code>{keyrow[0]}</code>\n  ⏳ Key Expiry: <code>{keyrow[1][:19]}</code>"
        creator_name=first or "Unknown"
        creator_user=("@"+uname) if uname else "-"
        phone_show=phone or "Not shared"
        user_count, user_rows = child_bot_stats(iid)
        phone_lines=[]
        for cuid,cname,cuname,cphone in user_rows:
            phone_lines.append(f"    • <code>{cuid}</code> | {cname or 'User'} | @{cuname or '-'} | 📱 {cphone or 'Not shared'}")
        users_preview="\n".join(phone_lines) if phone_lines else "    • No user records yet"
        lines.append(f"🧾 <b>{name}</b> — @{user or '?'}\n  🆔 Bot: <code>{iid}</code> | {status}\n  👤 Creator: <b>{creator_name}</b> {creator_user} | ID <code>{creator}</code>\n  📱 Creator Phone: <code>{phone_show}</code>\n  🛡 Admin ID: <code>{admin}</code>\n  👥 Shop Users: <b>{user_count}</b>\n  📱 Recent User Phones/IDs (max 20):\n{users_preview}\n  📅 Created: <code>{created}</code>\n  {key_line}")
    text="🧾 <b>BOT HISTORY / USERS</b>\n\n"+"\n\n".join(lines)
    # Telegram message limit protection: split long history into chunks.
    chunks=[text[i:i+3900] for i in range(0,len(text),3900)]
    await call.message.edit_text(chunks[0],reply_markup=kb_home(OWNER_ID) if len(chunks)==1 else None,parse_mode="HTML")
    for chunk in chunks[1:]:
        await call.message.answer(chunk,parse_mode="HTML")
    if len(chunks)>1:
        await call.message.answer("↩️ <b>Bot History complete.</b>",reply_markup=kb_home(OWNER_ID),parse_mode="HTML")
    await call.answer()

